~~~ file: KeydownCore.js
// KeydownCore.js: what the Keydown Svelte components share (they all sit next to KeydownBox.svelte, which holds the engine)!
//   prime()   makes sure the Keydown engine and every Keydown style are on the page (call it in onMount)
//   engine()  prime() and hand back window.Keydown (render, toText, editor, styleCategories, guide, file...)
//   dedent()  the text as written in a template: no blank first/last lines, and the shared indent taken off
import KeydownBox from './KeydownBox.svelte';
import { mount } from 'svelte';

let primed = false;
// KeydownBox.svelte carries the engine (window.Keydown) and every Keydown style; importing it loads the engine,
// and one hidden copy is shown once, so its styles are on the page even when your bundler injects styles on use
export function prime() {
    if (primed || typeof document === 'undefined') return;
    primed = true;
    const host = document.createElement('div');
    host.setAttribute('aria-hidden', 'true');
    host.style.cssText = 'position:absolute;width:0;height:0;overflow:hidden;visibility:hidden;pointer-events:none';
    document.body.appendChild(host);
    mount(KeydownBox, { target: host, props: { compact: true, toolbar: false, readonly: true, sound: false } });
}
export function engine() { prime(); return window.Keydown; }
// A Svelte action: when someone double-clicks an equation inside this element and edits it, the new LaTeX is written back
// into the text it was drawn from (so a component that only SHOWS Keydown text can still have its math edited)!
//   <div use:mathWriteBack={{ get: () => text, set: (t) => (text = t) }}>{@html html}</div>     the Nth equation of that text changes
//   <span use:mathWriteBack={{ whole: true, set: (tex) => (tex = tex) }}>                        the element shows ONE equation
// (an equation is only handled once: the inner-most element that has this action takes it)
export function mathWriteBack(node, params) {
    let p = params || {};
    const handler = (e) => {
        const d = e.detail;
        if (!d || !d.el || e.__kdMathHandled) return;
        const els = Array.from(node.querySelectorAll('.kd-math'));
        const i = els.indexOf(d.el);
        if (i < 0) return;
        if (p.whole) { if (typeof p.set === 'function') { e.__kdMathHandled = true; p.set(d.tex, d.display); } return; }
        if (typeof p.get !== 'function' || typeof p.set !== 'function' || typeof window.kdMathReplace !== 'function') return;
        const cur = String(p.get() == null ? '' : p.get());
        const next = window.kdMathReplace(cur, i, d.tex, d.display);
        e.__kdMathHandled = true;
        if (next !== cur) p.set(next);
    };
    node.addEventListener('kd-math-edited', handler);
    return { update(np) { p = np || {}; }, destroy() { node.removeEventListener('kd-math-edited', handler); } };
}
export function dedent(s) {
    const lines = String(s == null ? '' : s).replace(/\r\n?/g, '\n').split('\n');
    while (lines.length && !lines[0].trim()) lines.shift();
    while (lines.length && !lines[lines.length - 1].trim()) lines.pop();
    const pad = Math.min(...lines.filter((l) => l.trim()).map((l) => l.match(/^[ \t]*/)[0].length));
    return lines.map((l) => (isFinite(pad) ? l.slice(pad) : l).replace(/[ \t]+$/, '')).join('\n');
}
~~~

~~~ file: KeydownAnnotate.svelte
<!--
  KeydownAnnotate.svelte: draw on top of anything with Bitbook's Annotate inks (Gel Ink, Felt Pen, Highlighter, Neon,
  Crayon, and every theme pack: Frutiger Aero 1-4, Poolside 1-4, Cosmic, Metallic)!

  <KeydownAnnotate bind:ink>
    <p>Anything goes in here: text, a picture, a card, a KeydownText...</p>
  </KeydownAnnotate>
  <button onclick={() => (ink = '')}>Clear my drawing</button>

  Press ✏️ Draw, pick an ink and a color on the ink bar, draw over the content, then press Done (or Esc). The drawing
  is saved as text in `ink`, so you can keep it (a database, localStorage, a form field) and give it back later:
  start with <KeydownAnnotate ink={saved}> and the drawing is there again.

  Props: ink (bindable text: the strokes, '' for none), drawing (bindable, true while the ink bar is open),
         button (show the ✏️ Draw button, default true), readonly (show the drawing, but no drawing), class.
  Methods (bind:this={a}): a.draw() starts drawing, a.done() ends it, a.clear() erases everything.
  Needs KeydownCore.js and KeydownBox.svelte in the same folder. Svelte 5.
-->
<script>
    import { onMount, untrack } from 'svelte';
    import { prime } from './KeydownCore.js';

    let { children = undefined, ink = $bindable(''), drawing = $bindable(false), button = true, readonly = false, class: className = '' } = $props();
    let wrap = $state();
    let ready = $state(false);
    let shown = null;

    const AI = () => window.AnnotateInk;
    const layer = () => wrap && wrap.querySelector(':scope > svg.an-ink-layer');
    function show(text) {
        const old = layer(); if (old) old.remove();
        let list = [];
        try { list = text ? JSON.parse(text) : []; } catch (e) { list = []; }
        if (!Array.isArray(list) || !list.length || !AI()) return;
        const t = document.createElement('div');
        t.innerHTML = AI().layerHtml(list);
        const svg = t.firstElementChild;
        svg.setAttribute('width', Math.max(wrap.scrollWidth, wrap.clientWidth));
        svg.setAttribute('height', Math.max(wrap.scrollHeight, wrap.clientHeight));
        wrap.appendChild(svg);
    }
    export function draw() {
        if (!ready || readonly || !AI() || drawing) return;
        drawing = true;
        AI().start(wrap, { onStop: () => {
            const l = layer();
            const list = l ? AI().strokesOf(l) : [];
            shown = list.length ? JSON.stringify(list) : '';
            ink = shown;
            drawing = false;
        } });
    }
    export function done() { if (drawing && AI()) AI().stop(); }
    export function clear() { done(); ink = ''; }

    onMount(() => { prime(); ready = true; shown = ink; show(ink); return () => { if (drawing) done(); }; });
    // a drawing from outside (saved earlier, or cleared) is shown
    $effect(() => {
        const v = ink;
        if (!ready || v === shown) return;
        untrack(() => { shown = v; show(v); });
    });
</script>

<div class="kda {className}" bind:this={wrap}>
    {@render children?.()}
    {#if button && !readonly}
        <button type="button" class="kda-btn" class:on={drawing} title={drawing ? 'Done drawing' : 'Draw on this with Annotate inks'} onclick={() => (drawing ? done() : draw())}>{drawing ? '✔ Done' : '✏️ Draw'}</button>
    {/if}
</div>

<style>
    .kda { position: relative; }
    .kda-btn {
        position: absolute; top: 6px; right: 6px; z-index: 5; padding: 4px 12px; border-radius: 999px; cursor: pointer; font: 800 12px 'Segoe UI', system-ui, sans-serif;
        border: 1px solid #0369a1; background: linear-gradient(180deg, #ffffff, #d7effd); color: #075985; box-shadow: 0 1px 3px rgba(3, 105, 161, 0.35);
    }
    .kda-btn.on { background: linear-gradient(180deg, #86efac, #16a34a); border-color: #15803d; color: #052e16; }
</style>
