            if (qm) return qm[1] + '<span class="blockquote-list kd-bq kd-bq-' + { '!>': 'neon', '?>': 'glass', '>>': 'pull', '%>': 'gradient', '*>': 'marker', '+>': 'green', '->': 'red', '=>': 'dashed', '~>': 'whisper', '$>': 'paper', '#>': 'terminal', '^>': 'ribbon', '@>': 'bubble', '&>': 'card' }[qm[2]] + '">' + kdRender(qm[3]) + "</span>";
            const bm = /^::([a-z]+)(?:\{([^}]*)\})?$/.exec(trimmed);
