                            line(d, '#ffffff', w * 0.22, up(w, 0.24) + ' opacity="0.8"') + dots(d, '#ffffff', w * 0.14, w * 2.4, w * 0.5, ' transform="translate(' + (-w * 0.12).toFixed(2) + ' ' + (w * 0.1).toFixed(2) + ')" opacity="0.8"');
