                    case 'aero': // Frutiger Aero: a glossy sky-to-grass glass tube with bubbles drifting along it
                        return line(d, '#0369a1', w) + line(d, 'url(#ank-t-aero)', w * 0.72) + line(d, '#ffffff', w * 0.22, up(w, 0.2) + ' opacity="0.7"') +
