    {/each}
    {#if goal > 0}
        <span class="kdcn-goal" title={(counts.words || 0) + ' of ' + goal + ' words'}><i style:width={pct + '%'}></i></span>
        <span class="kdcn-pct">{pct}%{pct >= 100 ? ' — goal reached!' : ''}</span>
